/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('/workspace/tmp', pattern='\\\\.rds"'$'"', full.names=TRUE)) {
  cat('\\n===', basename(f), '===\\n')
  x <- readRDS(f)
  cat('class:', paste(class(x), collapse=','), '\\n')
  cat('typeof:', typeof(x), ' length:', length(x), '\\n')
  if (is.data.frame(x)) {
    cat('dim:', paste(dim(x), collapse=' x '), '\\n')
    cat('names:', paste(names(x), collapse=', '), '\\n')
    cat('rownames head:', paste(head(rownames(x)), collapse=', '), '\\n')
    print(head(x))
    cat('summary lfc/padj/pvalue:\\n')
    if ('log2FoldChange' %in% names(x)) print(summary(x"'$log2FoldChange))
    if ('"'pvalue' %in% names(x)) print(summary(x"'$pvalue))
    if ('"'padj' %in% names(x)) print(summary(x"'$padj))
    cat('"'NAs pvalue:', sum(is.na(x"'$pvalue)), '"'padj:', sum(is.na(x"'$padj)), '"'\\n')
  } else if (is.list(x)) {
    cat('names:', paste(names(x), collapse=', '), '\\n')
    str(x, max.level=1)
  } else {
    str(x)
  }
}
RS"

/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('/workspace/tmp', pattern='\\\\.rds"'$'"', full.names=TRUE)) {
  cat('\\n===', basename(f), '===\\n')
  x <- readRDS(f)
  cat('before class attr:', paste(class(x), collapse=','), '\\n')
  # remove class attr immediately
  x <- unclass(x)
  cat('unclassed typeof:', typeof(x), 'names:', paste(names(x), collapse=','), '\\n')
  if (is.list(x)) {
    cat('list names:', paste(names(x), collapse=','), '\\n')
    if ("'!is.null(x$log2FoldChange)) cat('"'lfc length', length(x"'$log2FoldChange), '"'padj length', length(x"'$padj), '"'pvalue length', length(x"'$pvalue), '"'\\n')
    if ('rownames' %in% names(x) || "'!is.null(attr(x,'"'rownames'))) cat('has rownames\\n')
    print(lapply(x, function(z) if (is.atomic(z)) head(z) else head(z)))
  }
}
RS"

/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('/workspace/tmp', pattern='\\\\.rds"'$'"', full.names=TRUE)) {
  cat('\\n===', basename(f), '===\\n')
  x <- readRDS(f)
  cat('slots:', paste(slotNames(x), collapse=', '), '\\n')
  for (s in slotNames(x)) {
    obj <- slot(x, s)
    cat('\\nslot', s, ' class:', paste(class(obj), collapse=','), ' typeof:', typeof(obj), '\\n')
    if (is.data.frame(obj)) {
      cat(' dim:', paste(dim(obj), collapse=' x '), 'names:', paste(names(obj), collapse=', '), '\\n')
      print(head(obj))
    } else if (is.atomic(obj)) {
      print(head(obj))
    } else if (is.list(obj)) {
      cat(' length:', length(obj), 'names:', paste(names(obj), collapse=', '), '\\n')
      str(obj, max.level=1)
    }
  }
}
RS"

/bin/bash -lc "Rscript - <<'RS'
x <- readRDS('/workspace/tmp/res_1vs97.rds')
a <- attributes(x)
ld <- a[['listData']]
cat('listData typeof:', typeof(ld), 'length:', length(ld), '\\n')
cat('listData names:', paste(names(ld), collapse=', '), '\\n')
for (nm in names(ld)) {
  v <- ld[[nm]]
  cat('\\n', nm, ' typeof=', typeof(v), ' class=', paste(class(v), collapse=','), ' length=', length(v), '\\n', sep='')
  if (is.atomic(v) && "'!is.null(dim(v))) cat('"'dim=', paste(dim(v), collapse='x'), '\\n')
  if (is.atomic(v)) {
    cat(' head=', paste(head(v), collapse=', '), '\\n')
    if (is.numeric(v)) cat(' summary=', paste(summary(v), collapse=' | '), '\\n')
  }
}
# metadata maybe
cat('\\nmetadata:\\n')
m <- a[['metadata']]
cat('typeof', typeof(m), 'length', length(m), 'names', paste(names(m), collapse=', '), '\\n')
if (is.list(m)) str(m, max.level=1)
RS"

